// Normalization and Entity Classification in n8n
const items = $input.all();
const results = [];

for (const item of items) {
  const row = item.json;
  const isFlight = row.aircraftIdentification || row.gufi || row.fdpsFlightStatus;
  const isNotam = row['ns3:text'] || row['ns2:identifier'] || row['ns6:airportname'];

  const entityType = isFlight ? 'Flight' : (isNotam ? 'NOTAM' : 'GeneralEvent');
  const eventId = isFlight && row.gufi ? `evt_flight_${row.gufi}` : (isNotam && row['ns2:identifier'] ? `evt_notam_${row['ns2:identifier']}` : `evt_n8n_${Date.now()}_${Math.random().toString(36).substring(7)}`);

  results.push({
    json: {
      eventId,
      organizationId: 'org_turning_point_default',
      sourceId: 'solace_n8n_pipeline',
      receivedAt: new Date().toISOString(),
      format: 'EXCEL_ROW',
      entityType,
      summary: isFlight ? `Flight ${row.aircraftIdentification || 'Unknown'} ${row.departurePoint || ''}->${row.arrivalPoint || ''}` : `NOTAM ${row['ns3:series'] || ''}${row['ns3:number'] || ''}`,
      status: 'PROCESSED',
      normalized: isFlight ? {
        flightNumber: row.aircraftIdentification,
        gufi: row.gufi,
        departureAirport: row.departurePoint,
        arrivalAirport: row.arrivalPoint,
        flightStatus: row.fdpsFlightStatus
      } : {
        notamCode: `${row['ns3:series'] || ''}${row['ns3:number'] || ''}`,
        location: row['ns6:icaoLocation'] || row['ns3:location'],
        text: row['ns3:text']
      },
      rawPayload: row
    }
  });
}

return results;
